import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { Applicant } from '../../types/app.types';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { useMemo } from 'react';
import { API_GATEWAY_BASE_URL } from '@/core/global-data/constants.data';
// import EyeIcon from '@/components/icons/EyeIcon';
import { Textarea } from '@/components/ui/textarea';
import EyeIcon from '@/components/icons/EyeIcon';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';

interface ApplicationPreviewProps {
    applicant: Applicant | null;
    openPreviewDialog: boolean;
    setOpenPreviewDialog: (open: boolean) => void;
}

/** Build public URL for stored CV (relative path from `Storage::store` or absolute URL). */
function resolveCvUrl(cvPath: string | null | undefined): string | null {
    const raw = cvPath?.trim();
    if (!raw) return null;
    if (/^https?:\/\//i.test(raw)) return raw;
    const path = raw.replace(/^\/+/, '');
    const base = String(API_GATEWAY_BASE_URL ?? '')
        .trim()
        .replace(/\/api\/?$/i, '')
        .replace(/\/+$/, '');
    if (!base) return `/storage/${path.startsWith('storage/') ? path.slice('storage/'.length) : path}`;
    const rel = path.startsWith('storage/') ? path : `storage/${path}`;
    return `${base}/${rel}`;
}

export default function ApplicationPreview({
    applicant,
    openPreviewDialog,
    setOpenPreviewDialog,
}: ApplicationPreviewProps) {
    const parsedSkills = useMemo(() => {
        const splitSkills = (value: string) =>
            value
                .split(/[\r\n,]+|\s+/)
                .map((s) => s.trim())
                .filter(Boolean);

        if (Array.isArray(applicant?.skills)) return applicant.skills;
        if (typeof applicant?.skills === 'string') return splitSkills(applicant.skills);
        if (applicant?.skills_text) return splitSkills(applicant.skills_text);
        return [];
    }, [applicant]);

    const cvUrl = useMemo(() => resolveCvUrl(applicant?.cv_path), [applicant?.cv_path]);

    return (
        <Dialog open={openPreviewDialog} onOpenChange={setOpenPreviewDialog}>
            <DialogContent
                dir="rtl"
                showCloseButton={false}
                className="max-w-[700px] rounded-xl border border-[#E8E7EA] bg-white-blue-50 p-5 sm:p-6"
            >
                <DialogHeader className="space-y-2">
                    <DialogTitle className="text-right text-[20px] font-semibold text-[#205295]">
                        <div className="flex items-center gap-2">
                            <EyeIcon width="20" height="20" className="text-primery-blue-400 bg-primery-blue-50 rounded-full p-1" />
                            معاينة المتقدم
                        </div>
                    </DialogTitle>
                    <div className="w-full border-b border-[#E8E7EA]" />
                </DialogHeader>

                <div className="mt-2 grid grid-cols-1 gap-3 sm:grid-cols-2">
                    <div className="space-y-1.5">
                        <label className="text-xs text-[#625E74]">اسم المتقدم</label>
                        <Input value={applicant?.name ?? ''} readOnly className="h-9 bg-white" />
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-xs text-[#625E74]">الوظيفة</label>
                        <Input
                            value={applicant?.job?.title ?? applicant?.job?.name ?? applicant?.job_title ?? ''}
                            readOnly
                            className="h-9 bg-white"
                        />
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-xs text-[#625E74]">المستوى</label>
                        <Input value={applicant?.level ?? ''} readOnly className="h-9 bg-white" />
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-xs text-[#625E74]">نوع العمل</label>
                        <Input value={applicant?.work_type ?? ''} readOnly className="h-9 bg-white" />
                    </div>
                </div>

                <div className="space-y-2 mt-2">
                    <label className="text-xs text-[#625E74]">السيرة الذاتية (CV)</label>
                    {cvUrl ? (
                        <a
                            href={cvUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center justify-between gap-3 rounded-lg border border-[#E8E7EA] bg-white px-3 py-2.5 text-sm text-primery-blue-700 transition hover:bg-primery-blue-50"
                        >
                            <span className="truncate font-medium">فتح / تحميل الملف</span>
                            <span className="shrink-0 text-xs text-[#625E74]">PDF / Word</span>
                        </a>
                    ) : (
                        <p className="rounded-lg border border-dashed border-[#E0E4EB] bg-[#FAFAFA] px-3 py-2.5 text-sm text-[#90868C]">
                            لم يُرفع ملف سيرة ذاتية
                        </p>
                    )}
                </div>

                <div className="space-y-2 mt-2">
                    <label className="text-primery-blue-900 font-medium text-[15px]">المهارات</label>
                    <Textarea value={parsedSkills.join(', ')} readOnly className="min-h-[100px] bg-white" />
                </div>

                <div className="space-y-2">
                    <label className="text-primery-blue-900 font-medium text-[15px]">ملاحظات</label>
                    <Textarea value={applicant?.notes ?? ''} readOnly className="min-h-[100px] bg-white" />
                </div>

                <div className="flex justify-start pt-2 gap-2">
                    <PrimaryButton type="button" onClick={() => setOpenPreviewDialog(false)}>
                        إغلاق
                    </PrimaryButton>
                    <SecondaryButton type="button" className="text-primery-blue-500 bg-primery-blue-50 rounded-md px-4 py-2" onClick={() => setOpenPreviewDialog(false)}>
                        تعديل المتقدم
                    </SecondaryButton>
                </div>
            </DialogContent>
        </Dialog>
    );
}
