import StatisticsCards from "@/components/cards/StatisticsCards";
import { useEffect, useState } from "react";
import { apiGet } from "@/lib/axios/axios-utils";
import { endpoints } from "@/lib/axios/axios-global";
import { Card } from "@/types/statistics";
import { applicantsStats } from "../types/app.types";
import UserRemoveIcon from "@/components/icons/UserRemoveIcon";
import ApplicantsList from "../components/applicantsList/ApplicantsList";
import { GroupIcon } from "lucide-react";

const ApplicantsPage = () => {
    const [stats, setStats] = useState<applicantsStats | null>(null);
    
    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.job.dashboard });
                setStats(res.data.data);
            } catch (err) {
                setStats(null);
            }
        };
        fetchStats();
    }, []);

    const cards: Card[] = [
        { text: 'إجمالي المتقدمين', num: stats?.total_applicants ?? 0, percent: 0, icon: <UserRemoveIcon /> },
        { text: 'إجمالي الوظائف', num: stats?.total_jobs ?? 0, percent: 0, icon: <GroupIcon /> },
    ];

    return <div>
        <StatisticsCards cards={cards} className="mt-6" />
        <ApplicantsList />
    </div>;
};

export default ApplicantsPage;